def findLatestTime(s: str) -> str:
    s_list = list(s)

    # Handle HH (Hours: 00 to 11)
    if s_list[0] == '?' and s_list[1] == '?':
        s_list[0] = '1'
        s_list[1] = '1'
    elif s_list[0] == '?':
        # If the second digit is 0 or 1, the first can be 1 (to get 10 or 11)
        # Otherwise, it must be 0 (to get 02, 03, etc.)
        if int(s_list[1]) <= 1:
            s_list[0] = '1'
        else:
            s_list[0] = '0'
    elif s_list[1] == '?':
        # If the first digit is 1, the max second digit is 1 (for 11)
        # If the first digit is 0, the max second digit is 9 (for 09)
        if s_list[0] == '1':
            s_list[1] = '1'
        else:
            s_list[1] = '9'

    # Handle MM (Minutes: 00 to 59)
    if s_list[3] == '?':
        s_list[3] = '5'
    if s_list[4] == '?':
        s_list[4] = '9'

    return "".join(s_list)
