import sys

def solve():
    # Increase recursion depth for deep BFS/DFS if necessary, 
    # though we use an iterative approach here.
    sys.setrecursionlimit(2000000)

    # Read H and W
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    H = int(input_data[0])
    W = int(input_data[1])
    grid = input_data[2:]

    # is_stuck[r][c] is True if the cell (r, c) is adjacent to a magnet
    is_stuck = [[False for _ in range(W)] for _ in range(H)]
    dr = [0, 0, 1, -1]
    dc = [1, -1, 0, 0]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == '#':
                for i in range(4):
                    nr, nc = r + dr[i], c + dc[i]
                    if 0 <= nr < H and 0 <= nc < W:
                        is_stuck[nr][nc] = True

    visited = [[False for _ in range(W)] for _ in range(H)]
    # last_seen_by_comp[r][c] stores the ID of the connected component 
    # that reached this 'stuck' cell to avoid double counting.
    last_seen_by_comp = [[-1 for _ in range(W)] for _ in range(H)]

    max_freedom = 0
    comp_id = 0

    for r in range(H):
        for c in range(W):
            # Start a BFS from every unvisited cell that is NOT a magnet and NOT stuck
            if grid[r][c] == '.' and not is_stuck[r][c] and not visited[r][c]:
                comp_id += 1
                count = 0
                stack = [(r, c)]
                visited[r][c] = True

                # Cells reachable in this component
                while stack:
                    curr_r, curr_c = stack.pop()
                    count += 1

                    for i in range(4):
                        nr, nc = curr_r + dr[i], curr_c + dc[i]
                        if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '.':
                            if is_stuck[nr][nc]:
                                # If it's a stuck cell, we can reach it but not move further.
                                # We count it only once per component.
                                if last_seen_by_comp[nr][nc] != comp_id:
                                    last_seen_by_comp[nr][nc] = comp_id
                                    count += 1
                            else:
                                # If it's not stuck and not visited, continue BFS
                                if not visited[nr][nc]:
                                    visited[nr][nc] = True
                                    stack.append((nr, nc))

                if count > max_freedom:
                    max_freedom = count

    # If max_freedom is still 0, it means every '.' cell is a 'stuck' cell.
    # In that case, the degree of freedom for any such cell is 1.
    if max_freedom == 0:
        for r in range(H):
            for c in range(W):
                if grid[r][c] == '.':
                    print(1)
                    return
    else:
        print(max_freedom)

if __name__ == "__main__":
