import sys

def solve():
    # Read input and group into three 4x4 polyominoes
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    raw_polys = []
    for i in range(0, 12, 4):
        raw_polys.append(input_data[i:i+4])

    # Convert polyominoes to sets of (r, c) coordinates relative to their top-left
    polys_coords = []
    total_hashes = 0
    for p in raw_polys:
        coords = []
        for r in range(4):
            for c in range(4):
                if p[r][c] == '#':
                    coords.append((r, c))
        polys_coords.append(coords)
        total_hashes += len(coords)

    # If total squares occupied by polyominoes is not 16, they can't fill a 4x4 grid
    if total_hashes != 16:
        print("No")
        return

    def rotate(coords):
        # Rotate 90 degrees clockwise: (r, c) -> (c, -r)
        return [(c, -r) for r, c in coords]

    def normalize(coords):
        # Shift coordinates so the minimum r and c are 0
        min_r = min(r for r, c in coords)
        min_c = min(c for r, c in coords)
        return sorted([(r - min_r, c - min_c) for r, c in coords])

    # Generate all 4 rotations for each polyomino
    all_rotations = []
    for coords in polys_coords:
        rots = []
        curr = coords
        for _ in range(4):
            rots.append(normalize(curr))
            curr = rotate(curr)
        # Remove duplicate rotations (e.g. for symmetric pieces)
        unique_rots = []
        for r in rots:
            if r not in unique_rots:
                unique_rots.append(r)
        all_rotations.append(unique_rots)

    # Try all combinations of rotations and translations
    # poly_idx: which polyomino we are placing (0, 1, 2)
    # grid: set of (r, c) already occupied
    def backtrack(poly_idx, grid):
        if poly_idx == 3:
            return len(grid) == 16

        for rot in all_rotations[poly_idx]:
            # Try all possible translations (dr, dc) such that the piece stays in 4x4
            for dr in range(-3, 4):
                for dc in range(-3, 4):
                    new_coords = []
                    possible = True
                    for r, c in rot:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < 4 and 0 <= nc < 4:
                            if (nr, nc) in grid:
                                possible = False
                                break
                            new_coords.append((nr, nc))
                        else:
                            possible = False
                            break

                    if possible and len(new_coords) == len(rot):
                        for nc in new_coords:
                            grid.add(nc)
                        if backtrack(poly_idx + 1, grid):
                            return True
                        for nc in new_coords:
                            grid.remove(nc)
        return False

    if backtrack(0, set()):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
