import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    # Initialize distance matrix with infinity
    INF = float('inf')
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    idx = 2
    for _ in range(M):
        u = int(input_data[idx]) - 1
        v = int(input_data[idx+1]) - 1
        w = int(input_data[idx+2])
        dist[u][v] = w
        idx += 3

    # Floyd-Warshall to find all-pairs shortest paths
    # Since there are no negative cycles, this is safe.
    for k in range(N):
        for i in range(N):
            if dist[i][k] == INF: continue
            for j in range(N):
                if dist[k][j] == INF: continue
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # DP state: dp[mask][last_v]
    # mask: bitmask of visited vertices
    # last_v: the last vertex in the walk
    # dp[mask][last_v] = minimum weight to visit vertices in mask ending at last_v
    num_states = 1 << N
    dp = [[INF] * N for _ in range(num_states)]

    # Base case: start at any vertex i
    for i in range(N):
        dp[1 << i][i] = 0

    # Iterate through all bitmasks
    for mask in range(1, num_states):
        for u in range(N):
            if dp[mask][u] == INF:
                continue

            # Try moving to vertex v that hasn't been visited or just to extend the walk
            # Actually, we only care about visiting NEW vertices to satisfy the condition.
            # The shortest path dist[u][v] already accounts for any intermediate vertices.
            for v in range(N):
                if not (mask & (1 << v)):
                    new_mask = mask | (1 << v)
                    if dist[u][v] != INF:
                        if dp[new_mask][v] > dp[mask][u] + dist[u][v]:
                            dp[new_mask][v] = dp[mask][u] + dist[u][v]

    # The answer is the minimum weight in dp[(1 << N) - 1][i] for all i
    ans = INF
    final_mask = (1 << N) - 1
    for i in range(N):
        if dp[final_mask][i] < ans:
            ans = dp[final_mask][i]

    if ans == INF:
        print("No")
    else:
        print(ans)

if __name__ == "__main__":
    solve()
