from functools import lru_cache

def numberOfBeautifulIntegers(low: int, high: int, k: int) -> int:
    def count_beautiful(n: int) -> int:
        s = str(n)

        @lru_cache(None)
        def dp(index, is_less, is_started, diff, remainder):
            # diff represents (count of even digits - count of odd digits)
            # We use an offset to keep diff non-negative for caching if needed, 
            # but Python's lru_cache handles negative integers fine.
            if index == len(s):
                return 1 if is_started and diff == 0 and remainder == 0 else 0

            res = 0
            # Option to not start the number yet (leading zeros)
            if not is_started:
                res += dp(index + 1, True, False, 0, 0)

            limit = int(s[index]) if not is_less else 9

            # Start or continue the number
            start_digit = 1 if not is_started else 0
            for digit in range(start_digit, limit + 1):
                new_is_less = is_less or (digit < limit)
                new_diff = diff + (1 if digit % 2 == 0 else -1)
                new_remainder = (remainder * 10 + digit) % k
                res += dp(index + 1, new_is_less, True, new_diff, new_remainder)

            return res

        return dp(0, False, False, 0, 0)

    # Result is the count up to high minus the count up to low-1
    return count_beautiful(high) - count_beautiful(low - 1)
