def minBalancedPartitions(s: str) -> int:
    n = len(s)
    # dp[i] will store the minimum number of balanced substrings for s[i:]
    dp = [float('inf')] * (n + 1)
    dp[n] = 0

    def is_balanced(sub_s):
        if not sub_s:
            return False
        counts = {}
        for char in sub_s:
            counts[char] = counts.get(char, 0) + 1

        # Check if all frequencies are the same
        freq_set = set(counts.values())
        return len(freq_set) == 1

    # Iterate backwards to fill the DP table
    for i in range(n - 1, -1, -1):
        # Optimization: Pre-calculate counts to avoid repeated work
        char_counts = {}
        max_freq = 0
        distinct_chars = 0

        for j in range(i, n):
            char = s[j]
            if char not in char_counts:
                char_counts[char] = 0
                distinct_chars += 1
            char_counts[char] += 1

            current_freq = char_counts[char]
            if current_freq > max_freq:
                max_freq = current_freq

            # A substring is balanced if:
            # total length == number of distinct characters * frequency of any character
            if (j - i + 1) == distinct_chars * max_freq:
                dp[i] = min(dp[i], 1 + dp[j + 1])

    return dp[0]
