def palindromePartition(s: str, k: int) -> int:
    n = len(s)

    # Precompute the cost to make s[i:j+1] a semi-palindrome
    # cost[i][j] stores the minimum changes for substring s[i...j]
    cost = [[0] * n for _ in range(n)]

    def get_semi_cost(sub):
        m = len(sub)
        if m < 2:
            return float('inf')

        min_changes = m  # Upper bound
        # Try all divisors d such that 1 <= d < m and m % d == 0
        for d in range(1, m // 2 + 1):
            if m % d == 0:
                current_changes = 0
                # For each group of indices with same modulo d
                # The group is sub[i], sub[i+d], sub[i+2d]...
                # But the definition says: indices with same modulo d form a palindrome.
                # This means for a fixed i (0 <= i < d), the sequence 
                # sub[i], sub[i+d], sub[i+2d], ..., sub[i + (m/d - 1)d] must be a palindrome.
                num_groups = d
                group_len = m // d
                for i in range(num_groups):
                    left = 0
                    right = group_len - 1
                    while left < right:
                        if sub[i + left * d] != sub[i + right * d]:
                            current_changes += 1
                        left += 1
                        right -= 1
                min_changes = min(min_changes, current_changes)
        return min_changes

    for i in range(n):
        for j in range(i + 1, n):
            cost[i][j] = get_semi_cost(s[i:j+1])

    # dp[i][j] is the min changes to partition s[0...j-1] into i semi-palindromes
    dp = [[float('inf')] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0

    for i in range(1, k + 1):
        # A semi-palindrome must have length at least 2
        for j in range(2 * i, n + 1):
            # Try all possible split points p
            # The last substring is s[p:j], which must have length >= 2
            for p in range(2 * (i - 1), j - 1):
                dp[i][j] = min(dp[i][j], dp[i-1][p] + cost[p][j-1])

    return int(dp[k][n])
