import math
from itertools import combinations

def findKthSmallest(coins, k):
    # Pre-process coins to remove redundant denominations (multiples of others)
    # This reduces the number of elements for the Inclusion-Exclusion Principle
    coins.sort()
    unique_coins = []
    for c in coins:
        is_multiple = False
        for u in unique_coins:
            if c % u == 0:
                is_multiple = True
                break
        if not is_multiple:
            unique_coins.append(c)

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        if a == 0 or b == 0: return 0
        return abs(a * b) // gcd(a, b)

    # Pre-calculate LCMs for all combinations to speed up the counting function
    lcm_groups = []
    n = len(unique_coins)
    for i in range(1, n + 1):
        group = []
        for combo in combinations(unique_coins, i):
            res_lcm = combo[0]
            for j in range(1, len(combo)):
                res_lcm = lcm(res_lcm, combo[j])
            group.append(res_lcm)
        lcm_groups.append(group)

    def count_upto(val):
        """Counts how many unique multiples exist <= val using Inclusion-Exclusion Principle."""
        total = 0
        for i, group in enumerate(lcm_groups):
            # i=0 represents 1-element sets (add), i=1 represents 2-element sets (subtract), etc.
            sign = 1 if i % 2 == 0 else -1
            current_sum = 0
            for l in group:
                current_sum += val // l
            total += sign * current_sum
        return total

    # Binary search for the k-th smallest amount
    low = 1
    high = min(unique_coins) * k
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if count_upto(mid) >= k:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return ans
