        inv = 0
        for i in range(len(p)):
            for j in range(i + 1, len(p)):
                if p[i] > p[j]:
                    inv += 1
        return inv

    min_ops = float('inf')
    found = False

    # Try all permutations of rows and columns
    # A permutation p of range(H) means the i-th row of B comes from the p[i]-th row of A
    for p_row in permutations(range(H)):
