import sys
from collections import deque

def solve():
    # Read H, W, T
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    H = int(input_data[0])
    W = int(input_data[1])
    T = int(input_data[2])
    grid = input_data[3:]

    start = None
    goal = None
    candies = []

    for r in range(H):
        for c in range(W):
            char = grid[r][c]
            if char == 'S':
                start = (r, c)
            elif char == 'G':
                goal = (r, c)
            elif char == 'o':
                candies.append((r, c))

    # Points of interest: Start, Goal, and Candies
    nodes = [start] + candies + [goal]
    n_candies = len(candies)
    n_nodes = len(nodes)

    # Precompute distances between all points of interest using BFS
    dist_matrix = [[float('inf')] * n_nodes for _ in range(n_nodes)]

    for i in range(n_nodes):
        sr, sc = nodes[i]
        dists = [[-1] * W for _ in range(H)]
        dists[sr][sc] = 0
        queue = deque([(sr, sc)])

        while queue:
            r, c = queue.popleft()
            d = dists[r][c]
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and dists[nr][nc] == -1:
                    dists[nr][nc] = d + 1
                    queue.append((nr, nc))

        for j in range(n_nodes):
            tr, tc = nodes[j]
            if dists[tr][tc] != -1:
                dist_matrix[i][j] = dists[tr][tc]

    # If goal is unreachable from start
    if dist_matrix[0][n_nodes - 1] > T:
        print("-1")
        return

    # DP with bitmask: dp[mask][i] is the min distance to visit candies in mask, ending at candy i
    # mask represents the set of candies (0 to n_candies-1)
    # nodes[1...n_candies] are candies
    dp = [[float('inf')] * n_candies for _ in range(1 << n_candies)]

    for i in range(n_candies):
        dp[1 << i][i] = dist_matrix[0][i + 1]

    for mask in range(1, 1 << n_candies):
        for i in range(n_candies):
            if dp[mask][i] > T:
                continue
            for next_candy in range(n_candies):
                if not (mask & (1 << next_candy)):
                    new_mask = mask | (1 << next_candy)
                    new_dist = dp[mask][i] + dist_matrix[i + 1][next_candy + 1]
                    if new_dist < dp[new_mask][next_candy]:
                        dp[new_mask][next_candy] = new_dist

    # Check the maximum number of candies such that dist(S->candies) + dist(last_candy->G) <= T
    max_candies = 0
    # Case 0 candies: already checked if goal is reachable
    for mask in range(1, 1 << n_candies):
        count = bin(mask).count('1')
        if count <= max_candies:
            continue
        for i in range(n_candies):
            if dp[mask][i] + dist_matrix[i + 1][n_nodes - 1] <= T:
                max_candies = count
                break

    print(max_candies)

if __name__ == "__main__":
    solve()
