def punishmentNumber(n: int) -> int:
    def can_partition(s, target):
        if not s:
            return target == 0

        # Try all possible split points for the current substring
        for i in range(1, len(s) + 1):
            val = int(s[:i])
            if val > target:
                break
            if can_partition(s[i:], target - val):
                return True
        return False

    total_punishment = 0
    for i in range(1, n + 1):
