def countCompleteSubstrings(word: str, k: int) -> int:
    def solve_segment(segment: str, k: int) -> int:
        n = len(segment)
        count = 0
        # m is the number of unique characters in the substring
        # Since each must appear k times, the length must be m * k
        # There are at most 26 unique lowercase English letters
        for m in range(1, 27):
            window_len = m * k
            if window_len > n:
                break

            freq = [0] * 26
            chars_with_k_freq = 0

            # Initialize the first window
            for i in range(window_len):
                idx = ord(segment[i]) - ord('a')
                freq[idx] += 1
                if freq[idx] == k:
                    chars_with_k_freq += 1
                elif freq[idx] == k + 1:
                    chars_with_k_freq -= 1

            if chars_with_k_freq == m:
                count += 1

            # Slide the window
            for i in range(window_len, n):
                # Remove leftmost
                left_idx = ord(segment[i - window_len]) - ord('a')
                if freq[left_idx] == k:
                    chars_with_k_freq -= 1
                freq[left_idx] -= 1
                if freq[left_idx] == k:
                    chars_with_k_freq += 1

                # Add rightmost
                right_idx = ord(segment[i]) - ord('a')
                if freq[right_idx] == k:
                    chars_with_k_freq -= 1
                freq[right_idx] += 1
                if freq[right_idx] == k:
                    chars_with_k_freq += 1

                if chars_with_k_freq == m:
                    count += 1
        return count

    total_complete = 0
    n = len(word)
    if n == 0:
        return 0

    # Split the word into segments where adjacent characters differ by at most 2
    start = 0
    for i in range(1, n + 1):
        if i == n or abs(ord(word[i]) - ord(word[i-1])) > 2:
            segment = word[start:i]
            total_complete += solve_segment(segment, k)
            start = i

    return total_complete
