    grid = [[False for _ in range(W)] for _ in range(H)]

    def find_empty():
        for r in range(H):
            for c in range(W):
                if not grid[r][c]:
                    return r, c
        return -1, -1

    def can_place(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for i in range(r, r + h):
            for j in range(c, c + w):
                if grid[i][j]:
                    return False
        return True

    def set_tile(r, c, h, w, val):
        for i in range(r, r + h):
            for j in range(c, c + w):
                grid[i][j] = val

    used = [False] * N

    def backtrack():
        r, c = find_empty()
        # If no empty cell is found, the grid is fully covered
        if r == -1:
            return True

