def numberOfPowerfulInt(start: int, finish: int, limit: int, s: str) -> int:
    def count_powerful(n_str: str, limit: int, s: str) -> int:
        n_len = len(n_str)
        s_len = len(s)

        if n_len < s_len:
            return 0

        # memoization for digit DP
        memo = {}

        def dp(idx, is_less, is_started):
            state = (idx, is_less, is_started)
            if state in memo:
                return memo[state]

            # If we reached the suffix part
            if idx == n_len - s_len:
                # Check if the remaining suffix 's' can fit within the constraints of n_str
                suffix_val = int(s)
                target_suffix_val = int(n_str[idx:])
                if is_less or suffix_val <= target_suffix_val:
                    return 1
                return 0

            res = 0
            # If we haven't started placing digits yet, we can skip this position
            if not is_started:
                res += dp(idx + 1, True, False)

            # Determine the upper bound for the current digit
            upper = int(n_str[idx]) if not is_less else 9
            upper = min(upper, limit)

            # Start digit from 1 if not started, else 0
            lower = 1 if not is_started else 0

            for digit in range(lower, upper + 1):
                new_is_less = is_less or (digit < int(n_str[idx]))
                res += dp(idx + 1, new_is_less, True)

            memo[state] = res
            return res

        return dp(0, False, False)

    return count_powerful(str(finish), limit, s) - count_powerful(str(start - 1), limit, s)
