def canTraverseAllPairs(nums: list[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    # If any number is 1, it cannot be connected to any other index
    # unless the array length is 1 (handled above).
    for x in nums:
        if x == 1:
            return False

    parent = list(range(n))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    # Map each prime factor to the first index in nums that has it
    prime_to_first_index = {}

    # Precompute smallest prime factor (SPF) for sieve up to max(nums)
    max_num = max(nums)
    spf = list(range(max_num + 1))
    for i in range(2, int(max_num**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_num + 1, i):
                if spf[j] == j:
                    spf[j] = i

    for i, val in enumerate(nums):
        temp = val
        while temp > 1:
            p = spf[temp]
            if p in prime_to_first_index:
                union(i, prime_to_first_index[p])
            else:
                prime_to_first_index[p] = i
            while temp % p == 0:
                temp //= p

    # Check if all indices belong to the same component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False

    return True
