def specialPerm(nums: list[int]) -> int:
    MOD = 10**9 + 7
    n = len(nums)
    # memo stores (mask, last_index)
    # mask: bitmask of visited indices
    # last_index: index of the last element added to the permutation
    memo = {}

    def solve(mask, last_idx):
        # Base case: all numbers have been used
        if mask == (1 << n) - 1:
            return 1

        state = (mask, last_idx)
        if state in memo:
            return memo[state]

        count = 0
        for next_idx in range(n):
            # If the number at next_idx hasn't been used yet
            if not (mask & (1 << next_idx)):
                # Check the special permutation condition
                if nums[last_idx] % nums[next_idx] == 0 or nums[next_idx] % nums[last_idx] == 0:
                    count = (count + solve(mask | (1 << next_idx), next_idx)) % MOD

        memo[state] = count
        return count

    total_permutations = 0
    # Start the permutation with each number in the array
    for i in range(n):
        total_permutations = (total_permutations + solve(1 << i, i)) % MOD

    return total_permutations
