from itertools import permutations

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    r_str = input_data[1]
    c_str = input_data[2]

    # Possible row patterns: exactly one A, one B, one C, and N-3 dots
    chars = ['A', 'B', 'C'] + ['.'] * (n - 3)
    # Use set to get unique permutations
    row_patterns = sorted(list(set(permutations(chars))))

    # We need to pick N rows from row_patterns such that:
    # 1. Each column has exactly one A, one B, one C.
    # 2. Leftmost non-dot in row i is r_str[i].
    # 3. Topmost non-dot in column j is c_str[j].

    # Filter patterns for each row based on condition 2
    valid_patterns_per_row = []
    for i in range(n):
        target = r_str[i]
        valid = []
        for p in row_patterns:
            # Find first non-dot
            first = None
            for char in p:
                if char != '.':
                    first = char
                    break
            if first == target:
                valid.append(p)
        valid_patterns_per_row.append(valid)

    grid = [None] * n

    def backtrack(row_idx):
        if row_idx == n:
            # Check condition 1 (columns) and 3 (topmost)
            for j in range(n):
                col_chars = [grid[i][j] for i in range(n) if grid[i][j] != '.']
                # Exactly one A, B, C
                if sorted(col_chars) != ['A', 'B', 'C']:
                    return False
                # Topmost matches C[j]
                if col_chars[0] != c_str[j]:
                    return False
            return True

        for p in valid_patterns_per_row[row_idx]:
            grid[row_idx] = p

            # Pruning: check if any column already has duplicates of A, B, or C
            possible = True
            for j in range(n):
                counts = {'A': 0, 'B': 0, 'C': 0}
                for i in range(row_idx + 1):
                    char = grid[i][j]
                    if char != '.':
                        counts[char] += 1
                        if counts[char] > 1:
                            possible = False
                            break
                if not possible: break

            if possible:
                if backtrack(row_idx + 1):
                    return True
        return False

    if backtrack(0):
        print("Yes")
        for row in grid:
            print("".join(row))
    else:
        print("No")

