    line1 = sys.stdin.readline()
    if not line1:
        return
    m = int(line1.strip())

    # Read the three strings
    s = []
    for _ in range(3):
        s.append(sys.stdin.readline().strip())

    ans = float('inf')
    found = False

    # Iterate through each possible digit '0'-'9' that we want to match
    for digit in "0123456789":
        # Find all indices (times mod M) where this digit appears in each reel
        indices = []
        for i in range(3):
            idx_list = [j for j, char in enumerate(s[i]) if char == digit]
            indices.append(idx_list)

        # If any reel doesn't contain the digit, we can't match this digit
        if not indices[0] or not indices[1] or not indices[2]:
            continue

        # Try all permutations of the reels to decide which one to stop first, second, and third
        for p in permutations(range(3)):
            # For a fixed order of reels (p[0], p[1], p[2]), find the earliest time
            # We want to minimize the time for this specific permutation and digit
            # Since M is small (100), we can just pick the smallest available time for each
            for t0 in indices[p[0]]:
                for t1_base in indices[p[1]]:
                    # t1 must be different from t0, and t1 % M == t1_base
                    t1 = t1_base
                    if t1 == t0:
                        t1 += m

                    for t2_base in indices[p[2]]:
                        # t2 must be different from t0 and t1, and t2 % M == t2_base
                        t2 = t2_base
                        while t2 == t0 or t2 == t1:
                            t2 += m

                        # The time taken for this configuration is the maximum of the three stop times
                        current_max = max(t0, t1, t2)
                        if current_max < ans:
                            ans = current_max
                            found = True

    if not found:
        print("-1")
    else:
        print(ans)

